<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRouter} from 'vue-router'
import {Plus,Save,Send,Eye,LogOut,LoaderCircle,Search,LockKeyhole,Download,ArrowLeft,RefreshCw} from 'lucide-vue-next'
import ReportView from './Report.vue'
import {api,post,setCsrf,date,uid,sections,labels,download,type Report} from './lib'
const router=useRouter();const user=ref('');const username=ref('admin');const password=ref('');const error=ref('');const notice=ref('');const busy=ref(false);const overview=ref<any>();const version=ref('');const bank=ref<any>();const status=ref('');const dirty=ref(false);const search=ref('');const page=ref(1);const section=ref('all');const selectedFacet=ref('career.value');const preview=ref<Report>();const currentPassword=ref('');const newPassword=ref('');const newTitle=ref('');const showPassword=ref(false)
const submissions=ref<any[]>([]);const submissionTotal=ref(0);const submissionSearch=ref('');const selectedSubmission=ref<any>();const submissionLoading=ref(false)
const editable=computed(()=>status.value==='draft');const filtered=computed(()=>bank.value?.questions.filter((q:any)=>(section.value==='all'||q.section===section.value)&&(!search.value||`${q.id} ${q.text}`.includes(search.value)))||[]);const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/20)));const visible=computed(()=>filtered.value.slice((Math.min(page.value,pages.value)-1)*20,Math.min(page.value,pages.value)*20));const facet=computed(()=>overview.value?.facets[selectedFacet.value]);
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function refresh(){overview.value=await api('/api/admin/overview');if(!version.value)version.value=overview.value.current}
async function refreshSubmissions(){const result=await api<{total:number;items:any[]}>('/api/admin/submissions');submissions.value=result.items;submissionTotal.value=result.total}
const filteredSubmissions=computed(()=>submissions.value.filter(item=>!submissionSearch.value||`${item.studentId} ${item.studentName} ${item.type} ${item.id}`.toLowerCase().includes(submissionSearch.value.toLowerCase())))
async function openSubmission(id:string){submissionLoading.value=true;error.value='';try{selectedSubmission.value=await api(`/api/admin/submissions/${encodeURIComponent(id)}`)}catch(e){error.value=(e as Error).message}finally{submissionLoading.value=false}}
async function exportSubmission(id:string){try{const response=await fetch(import.meta.env.BASE_URL.replace(/\/$/,'')+`/api/admin/submissions/${encodeURIComponent(id)}/export`,{credentials:'same-origin',cache:'no-store'});if(!response.ok){const body=await response.json().catch(()=>({detail:'导出失败，请重试。'}));throw new Error(body.detail||'导出失败，请重试。')}download(`mbti-submission-${id}.json`,await response.blob())}catch(e){error.value=(e as Error).message}}
async function loadVersion(id:string){if(dirty.value&&!confirm('当前草稿尚未保存，切换将放弃这些修改。继续吗？'))return;const data=await api(`/api/admin/versions/${encodeURIComponent(id)}`);version.value=id;bank.value=data.bank;bank.value.recommendations ||= {};bank.value.template={...overview.value.template,...bank.value.template};status.value=data.status;dirty.value=false;page.value=1;newTitle.value=`${data.bank.title} · 修订`;}
async function login(){await run(async()=>{const r=await post('/api/admin/login',{username:username.value,password:password.value});user.value=r.username;setCsrf(r.csrf);password.value='';await Promise.all([refresh(),refreshSubmissions()]);await loadVersion(version.value)})}
async function logout(){await run(async()=>{await post('/api/admin/logout',{});user.value='';setCsrf('');bank.value=undefined})}
async function createDraft(){if(dirty.value&&!confirm('当前编辑尚未保存，仍创建新草稿吗？'))return;await run(async()=>{const r=await post('/api/admin/versions',{source:version.value,title:newTitle.value||'知序问卷修订'});dirty.value=false;await refresh();await loadVersion(r.id);notice.value='新草稿已创建，已发布版本保持不变。'})}
async function saveDraft(){await api(`/api/admin/versions/${encodeURIComponent(version.value)}`,{method:'PUT',body:JSON.stringify({bank:bank.value})});dirty.value=false;notice.value='草稿已保存并通过题量与归属检查。'}
async function publish(){if(!confirm('发布后新用户将使用此版本；已有草稿继续使用原版本。确认发布吗？'))return;await run(async()=>{await saveDraft();await post(`/api/admin/versions/${encodeURIComponent(version.value)}/publish`,{});await refresh();await loadVersion(version.value);notice.value='发布成功。'})}
function updateRecommendation(direction:string,text:string){bank.value.recommendations[selectedFacet.value]||={};bank.value.recommendations[selectedFacet.value][direction]=text;dirty.value=true}
async function makePreview(){await run(async()=>{if(editable.value&&dirty.value)await saveDraft();const answers=Object.fromEntries(bank.value.questions.map((q:any,i:number)=>[q.id,(i%7)-3]));preview.value=await post(`/api/admin/versions/${encodeURIComponent(version.value)}/preview`,{version:version.value,mode:'full',answers,submissionId:uid()})})}
async function changePassword(){await run(async()=>{await post('/api/admin/password',{current:currentPassword.value,password:newPassword.value});user.value='';setCsrf('');currentPassword.value='';newPassword.value='';notice.value='密码已更换，请重新登录。'})}
function beforeClose(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
const removeGuard=router.beforeEach(()=>{if(dirty.value&&!confirm('草稿尚未保存，确定离开后台吗？'))return false})
onMounted(async()=>{window.addEventListener('beforeunload',beforeClose);try{const r=await api('/api/admin/me');user.value=r.username;setCsrf(r.csrf);await refresh();await Promise.all([loadVersion(version.value),refreshSubmissions()])}catch{/* unauthenticated is the normal initial state */}})
onBeforeUnmount(()=>{removeGuard();window.removeEventListener('beforeunload',beforeClose)})
</script>

<template>
 <div v-if="preview" class="admin-preview"><div class="page no-print"><div class="alert">以下使用模拟答案预览，不计入客户统计。<button class="secondary" @click="preview=undefined">返回后台</button></div></div><ReportView :report="preview" preview/></div>
 <div v-else class="page admin-page">
  <div class="page-heading"><div><span class="eyebrow">CONTENT STUDIO</span><h1>内容管理</h1></div><button v-if="user" class="secondary" @click="logout"><LogOut :size="16"/>退出 {{user}}</button></div>
  <div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div>
  <form v-if="!user" class="surface login-panel" @submit.prevent="login"><LockKeyhole :size="28" class="accent"/><h2 class="serif">管理员登录</h2><p class="muted">用于维护原创题库与建议内容。</p><label class="field">账号<input v-model="username" autocomplete="username" required maxlength="80"></label><label class="field">密码<input v-model="password" type="password" autocomplete="current-password" required maxlength="200"></label><button class="primary" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="16"/>{{busy?'正在登录…':'登录'}}</button></form>
  <template v-else-if="overview">
   <section class="surface admin-section submission-section"><div class="panel-heading"><div><h2>答题提交</h2><p class="muted small">共 {{submissionTotal}} 份已提交数据，可查看记录或逐份导出。</p></div><div class="button-row"><button v-if="selectedSubmission" class="secondary" @click="selectedSubmission=undefined"><ArrowLeft :size="16"/>返回列表</button><button class="secondary" :disabled="submissionLoading" @click="run(refreshSubmissions)"><RefreshCw :size="16"/>刷新</button></div></div>
    <div v-if="selectedSubmission" class="submission-detail"><div class="submission-meta"><div><span>姓名</span><strong>{{selectedSubmission.studentName}}</strong></div><div><span>学号</span><strong>{{selectedSubmission.studentId}}</strong></div><div><span>测试</span><strong>{{selectedSubmission.mode==='basic'?'精简 99 题':'详细 300 题'}}</strong></div><div><span>结果</span><strong>{{selectedSubmission.report?.type}}</strong></div><div><span>提交时间</span><strong>{{date(selectedSubmission.created)}}</strong></div><div><span>问卷版本</span><strong>{{selectedSubmission.version}}</strong></div></div><div class="panel-heading answer-heading"><h3>作答记录 · {{Object.keys(selectedSubmission.answers||{}).length}} 题</h3><button class="primary" @click="exportSubmission(selectedSubmission.id)"><Download :size="16"/>导出本份 JSON</button></div><div class="stats-table answer-table"><table><thead><tr><th>题目编号</th><th>回答值</th></tr></thead><tbody><tr v-for="[id,value] in Object.entries(selectedSubmission.answers||{})" :key="id"><td>{{id}}</td><td>{{value===null?'不适用':labels[Number(value)+3]}}</td></tr></tbody></table></div><ReportView v-if="selectedSubmission.report" :report="selectedSubmission.report" preview/></div>
    <template v-else><label class="field submission-search">搜索学号、姓名、结果或编号<input v-model="submissionSearch" placeholder="输入关键词"></label><div class="stats-table"><table><thead><tr><th>学号</th><th>姓名</th><th>测试</th><th>结果</th><th>提交时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in filteredSubmissions" :key="item.id"><td>{{item.studentId}}</td><td>{{item.studentName}}</td><td>{{item.mode==='basic'?'99 题':'300 题'}}</td><td>{{item.type}}</td><td>{{date(item.created)}}</td><td><div class="button-row"><button class="text-button" @click="openSubmission(item.id)"><Eye :size="15"/>查看</button><button class="text-button" @click="exportSubmission(item.id)"><Download :size="15"/>导出</button></div></td></tr></tbody></table><p v-if="!filteredSubmissions.length" class="muted">{{submissionTotal?'没有符合条件的记录。':'暂无已提交数据。'}}</p></div></template>
   </section>
   <template v-if="bank">
   <div class="admin-top surface"><div class="field"><label for="version-select">题库版本</label><select id="version-select" :value="version" @change="run(()=>loadVersion(($event.target as HTMLSelectElement).value))"><option v-for="v in overview.versions" :key="v.id" :value="v.id">{{v.id}} · {{v.status==='draft'?'草稿':'已发布'}}{{v.id===overview.current?' · 当前入口':''}}</option></select></div><div class="tag">{{editable?'可编辑草稿':'已发布 · 不可覆盖'}}</div><div class="button-row"><button class="secondary" :disabled="busy" @click="makePreview"><Eye :size="16"/>报告预览</button><button v-if="editable" class="secondary" :disabled="busy||!dirty" @click="run(saveDraft)"><Save :size="16"/>保存草稿</button><button v-if="editable" class="primary" :disabled="busy" @click="publish"><Send :size="16"/>校验并发布</button></div></div>
   <section class="surface admin-section"><h2>版本与发布</h2><p class="muted small">已发布问卷不可覆盖。新版本会保留旧问卷，避免用户续答时题目变化。精简 99 / 详细 300、共用题与各模块数量在服务端校验。</p><label class="field">问卷标题<input v-model="bank.title" :disabled="!editable" maxlength="160" @input="dirty=true"></label><div class="new-version"><label class="field">新草稿名称<input v-model="newTitle" maxlength="160"></label><button class="secondary" :disabled="busy" @click="createDraft"><Plus :size="16"/>复制为新草稿</button></div></section>
   <section class="surface admin-section"><div class="panel-heading"><h2>题目维护</h2><span>{{filtered.length}} 道</span></div><div class="admin-filters"><label class="field">搜索题号或文字<input v-model="search" placeholder="输入关键词" @input="page=1"></label><label class="field">章节<select v-model="section" @change="page=1"><option value="all">全部</option><option value="base">基础人格 99 题</option><option value="personality">人格深化 21 题</option><option value="career">职业 60 题</option><option value="social">社交 60 题</option><option value="romance">恋爱 60 题</option></select></label></div><article v-for="q in visible" :key="q.id" class="admin-question"><div><strong>{{q.id}}</strong><span class="tag">{{q.dimension||q.facet}}</span></div><label class="field">题目文字<textarea v-model="q.text" :disabled="!editable" rows="2" maxlength="240" @input="dirty=true"></textarea></label><label v-if="q.dimension" class="field inline-field">人格维度<select v-model="q.dimension" :disabled="!editable" @change="q.facet=q.dimension;dirty=true"><option v-for="d in ['EI','SN','TF','JP']" :key="d" :value="d">{{d}}</option></select></label><label v-else class="field inline-field">专项主题<select v-model="q.facet" :disabled="!editable" @change="dirty=true"><template v-for="(v,key) in overview.facets" :key="key"><option v-if="String(key).startsWith(q.section+'.')" :value="key">{{(v as any).title}}</option></template></select></label><label class="field inline-field">评分方向<select v-model="q.direction" :disabled="!editable" @change="dirty=true"><option :value="1">正向 +1</option><option :value="-1">反向 -1</option></select></label></article><p v-if="!filtered.length" class="empty-state">没有匹配的题目。</p><div class="pagination"><button class="secondary" :disabled="page<=1" @click="page--">上一页</button><span>{{Math.min(page,pages)}} / {{pages}}</span><button class="secondary" :disabled="page>=pages" @click="page++">下一页</button></div></section>
   <section class="surface admin-section"><h2>报告模板</h2><p class="muted small">模板与题库一同发布并固定版本，不改变既有报告。</p><label v-for="(title,key) in {overview:'概览解释',reflection:'情境反思',review:'专项复盘'}" :key="key" class="field">{{title}}<textarea v-model="bank.template[key]" :disabled="!editable" rows="3" maxlength="1200" @input="dirty=true"></textarea></label></section>
   <section class="surface admin-section"><h2>专项建议库</h2><p class="muted small">按主题与偏好方向编辑。建议应含具体行动和核对方式，避免诊断、职业命定或关系预测。发布后生效。</p><label class="field">观察主题<select v-model="selectedFacet"><option v-for="(v,key) in overview.facets" :key="key" :value="key">{{key}} · {{(v as any).title}}</option></select></label><label v-for="direction in ['high','low']" :key="direction" class="field">{{direction==='high'?'高位置一端的建议':'低位置一端的建议'}}<textarea :value="bank.recommendations[selectedFacet]?.[direction]??facet?.[direction]" :disabled="!editable" rows="4" maxlength="1200" @input="updateRecommendation(direction,($event.target as HTMLTextAreaElement).value)"></textarea></label></section>
   <section class="surface admin-section"><h2>使用汇总</h2><p class="fineprint">汇总事件仅包含匿名开始、到达章节与完成次数，不包含逐题答案和身份信息。提交数据请在上方“答题提交”中查看。</p><div class="stats-table"><table><thead><tr><th>日期（UTC）</th><th>测试</th><th>事件</th><th>次数</th></tr></thead><tbody><tr v-for="(s,i) in overview.stats" :key="i"><td>{{s.day}}</td><td>{{s.mode==='basic'?'99 题':'300 题'}}</td><td>{{s.kind==='started'?'开始':s.kind==='completed'?'完成':`到达${sections[s.kind.split(':')[1]]||'章节'}`}}</td><td>{{s.count}}</td></tr></tbody></table><p v-if="!overview.stats.length" class="muted">暂无客户测试记录。</p></div></section>
   <section class="surface admin-section"><div class="panel-heading"><h2>账号安全</h2><button class="text-button" @click="showPassword=!showPassword">{{showPassword?'收起':'修改密码'}}</button></div><form v-if="showPassword" @submit.prevent="changePassword"><label class="field">当前密码<input v-model="currentPassword" type="password" autocomplete="current-password" required></label><label class="field">新密码（至少 9 个字符）<input v-model="newPassword" type="password" autocomplete="new-password" minlength="9" maxlength="200" required></label><button class="secondary" :disabled="busy">修改并重新登录</button></form><p v-for="log in overview.logs" :key="log.created" class="fineprint">{{date(log.created)}} · {{log.action}}</p></section>
   </template>
  </template>
 </div>
</template>
